using JSO.Domain; using Microsoft.EntityFrameworkCore;
namespace JSO.Infrastructure;
public sealed class JsoDbContext(DbContextOptions<JsoDbContext> options) : DbContext(options) { public DbSet<Club> Clubs => Set<Club>(); public DbSet<Season> Seasons => Set<Season>(); public DbSet<Competition> Competitions => Set<Competition>(); public DbSet<Team> Teams => Set<Team>(); public DbSet<Player> Players => Set<Player>(); public DbSet<StaffMember> StaffMembers => Set<StaffMember>(); public DbSet<Match> Matches => Set<Match>(); public DbSet<MatchEvent> MatchEvents => Set<MatchEvent>(); public DbSet<Article> Articles => Set<Article>(); protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.Entity<Club>().HasIndex(x=>x.ShortName).IsUnique(); modelBuilder.Entity<Season>().HasIndex(x=>x.Name).IsUnique(); modelBuilder.Entity<Article>().HasIndex(x=>x.Slug).IsUnique(); modelBuilder.Entity<Match>().HasIndex(x=>new{x.KickoffAt,x.Status}); modelBuilder.Entity<Player>().HasIndex(x=>new{x.TeamId,x.ShirtNumber}); modelBuilder.Entity<Club>().HasData(new Club { Id=Guid.Parse("8d8c1ef6-1c9d-4d1c-9a0f-8a5b6b5c1001"), Name="Jeunesse Sportive de Oudhref", ShortName="JSO", Country="Tunisie", City="Oudhref" }); } }
